<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use ReadyFinance\{Core,Finance,Accounting,ChartService,AccountManagementService,TransactionEditingService,Fault};
$c=new Core();if(!str_starts_with((string)$c->query('SELECT DATABASE()')->fetchColumn(),'readyfinance_entrytest_'))throw new RuntimeException('Run only on an isolated entry-test database.');
$h=(int)$c->query('SELECT MIN(id) FROM households')->fetchColumn();$u=(int)$c->query('SELECT MIN(id) FROM users')->fetchColumn();$a=new Accounting($c);$f=new Finance($c);$chart=new ChartService($c);$manage=new AccountManagementService($c);$edit=new TransactionEditingService($c);$date=$c->today($h);$prefix='edit-test:'.bin2hex(random_bytes(5));$count=0;
function ok($value,$label){global $count;if(!$value)throw new RuntimeException('FAIL: '.$label);$count++;echo 'PASS: '.$label.PHP_EOL;}
function fails($fn,$label){try{$fn();}catch(Fault $e){ok(true,$label);return;}throw new RuntimeException('FAIL: '.$label);}
function equalMoney($a,$b):bool{return bccomp((string)$a,(string)$b,6)===0;}
function correction($t,$changes,$key){global $edit,$h,$u;$p=$edit->details($h,$t['uuid'])['payload'];return $edit->edit($h,$u,['uuid'=>$t['uuid'],'row_version'=>$t['row_version'],'reason'=>'Synthetic correction','payload'=>array_replace($p,$changes)],$key);}
$before=$c->query('SELECT COUNT(*) FROM journal_lines')->fetchColumn();$manage->upgrade();$manage->upgrade();ok($c->query('SELECT COUNT(*) FROM journal_lines')->fetchColumn()==$before,'Repeated editing upgrades preserve all journal lines');
$bank=$f->create($h,$u,'account',['name'=>'Edit bank '.$prefix,'type'=>'bank','opening'=>'0','date'=>$date],$prefix.':bank');$bank2=$f->create($h,$u,'account',['name'=>'Second bank '.$prefix,'type'=>'bank','opening'=>'0','date'=>$date],$prefix.':bank2');
$expense=$chart->create($h,$u,['kind'=>'expense','name'=>'Edit expense '.$prefix],$prefix.':expense');$income=$chart->create($h,$u,['kind'=>'income','name'=>'Edit income '.$prefix],$prefix.':income');$cat=$c->one('SELECT * FROM categories WHERE household_id=? AND ledger_id=(SELECT id FROM ledger_accounts WHERE uuid=?)',[$h,$expense['uuid']]);$inc=$c->one('SELECT * FROM categories WHERE household_id=? AND ledger_id=(SELECT id FROM ledger_accounts WHERE uuid=?)',[$h,$income['uuid']]);$uncat=$c->one("SELECT ca.* FROM categories ca JOIN ledger_accounts l ON l.id=ca.ledger_id WHERE ca.household_id=? AND l.system_key='uncategorized_expense'",[$h]);$member=$c->one('SELECT uuid FROM members WHERE household_id=? LIMIT 1',[$h]);
$t=$a->post($h,$u,['type'=>'expense','account_uuid'=>$bank['uuid'],'category_uuid'=>$cat['uuid'],'amount'=>'40','date'=>$date,'description'=>'Synthetic split expense','splits'=>[['category_uuid'=>$cat['uuid'],'amount'=>'25','member_uuid'=>$member['uuid'],'project'=>'Test project','tags'=>'test-tag'],['category_uuid'=>$uncat['uuid'],'amount'=>'15','tags'=>'second-tag']]],$prefix.':split');
$input=['uuid'=>$t['uuid'],'row_version'=>$t['row_version'],'reason'=>'Correct split total','payload'=>$edit->details($h,$t['uuid'])['payload']];$input['payload']['amount']='45';$input['payload']['splits'][1]['amount']='20';$result=$edit->edit($h,$u,$input,$prefix.':edit-split');$new=$c->scope('transactions',$result['uuid'],$h);ok($c->scope('transactions',$t['uuid'],$h)['status']==='reversed'&&$new['replaces_id']==$t['id'],'Correction retains original and links its replacement');ok(equalMoney($c->balance($h,(int)$c->scope('accounts',$bank['uuid'],$h)['ledger_id']),'-45'),'Correction changes cash by the difference only');$details=$edit->details($h,$new['uuid']);ok($details['payload']['splits'][0]['tags']==='test-tag'&&$details['payload']['splits'][0]['member_uuid']===$member['uuid']&&$details['payload']['splits'][0]['project']==='Test project','Editing preserves individual split tags, member and project');
$n=$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn();ok($edit->edit($h,$u,$input,$prefix.':edit-split')['uuid']===$new['uuid']&&$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn()==$n,'Correction retries do not duplicate postings');fails(fn()=>$edit->edit($h,$u,$input,$prefix.':stale'),'Editing an already changed original is rejected');
$bad=$edit->details($h,$new['uuid'])['payload'];$bad['amount']='99';$n=$c->query('SELECT COUNT(*) FROM journal_lines')->fetchColumn();fails(fn()=>$edit->edit($h,$u,['uuid'=>$new['uuid'],'row_version'=>$new['row_version'],'reason'=>'Bad totals','payload'=>$bad],$prefix.':invalid'),'Invalid split correction is rejected');ok($c->scope('transactions',$new['uuid'],$h)['status']==='posted'&&$c->query('SELECT COUNT(*) FROM journal_lines')->fetchColumn()==$n,'Failed replacement rolls back its reversal and all journal lines');
$month=substr($date,0,7);$c->query('UPDATE periods SET locked=1 WHERE household_id=? AND month=?',[$h,$month]);try{fails(fn()=>correction($new,['description'=>'Locked attempt'],$prefix.':locked'),'Corrections in a locked original period are rejected');}finally{$c->query('UPDATE periods SET locked=0 WHERE household_id=? AND month=?',[$h,$month]);}
$salary=$a->post($h,$u,['type'=>'income','account_uuid'=>$bank['uuid'],'category_uuid'=>$inc['uuid'],'amount'=>'10','date'=>$date],$prefix.':salary');$r=correction($salary,['amount'=>'15'],$prefix.':salary-edit');ok(equalMoney($c->scope('transactions',$r['uuid'],$h)['amount'],'15'),'Income amount can be corrected');
$transfer=$a->post($h,$u,['type'=>'transfer','account_uuid'=>$bank['uuid'],'to_account_uuid'=>$bank2['uuid'],'amount'=>'4','date'=>$date],$prefix.':transfer');$r=correction($transfer,['amount'=>'6'],$prefix.':transfer-edit');ok(equalMoney($c->balance($h,(int)$c->scope('accounts',$bank2['uuid'],$h)['ledger_id']),'6'),'Transfer correction updates both accounts');
$opening=$a->post($h,$u,['type'=>'opening','account_uuid'=>$bank2['uuid'],'amount'=>'100','date'=>$date],$prefix.':opening');correction($opening,['amount'=>'120'],$prefix.':opening-edit');ok(equalMoney($c->balance($h,(int)$c->scope('accounts',$bank2['uuid'],$h)['ledger_id']),'126'),'Opening balance is corrected through balanced journals');
$bill=$f->create($h,$u,'bill',['name'=>'Edit bill '.$prefix,'amount'=>'20','due_date'=>$date,'category_uuid'=>$cat['uuid']],$prefix.':bill');$payment=$a->post($h,$u,['type'=>'expense','account_uuid'=>$bank['uuid'],'category_uuid'=>$cat['uuid'],'bill_uuid'=>$bill['uuid'],'amount'=>'5','date'=>$date],$prefix.':billpay');correction($payment,['amount'=>'7'],$prefix.':billpay-edit');$billId=$c->scope('bills',$bill['uuid'],$h)['id'];ok(equalMoney($c->query('SELECT SUM(amount) FROM bill_allocations WHERE household_id=? AND bill_id=?',[$h,$billId])->fetchColumn(),'7'),'Edited partial payment preserves the correct bill allocation');
$loan=$f->create($h,$u,'debt',['name'=>'Edit loan '.$prefix,'direction'=>'borrowed','amount'=>'100','account_uuid'=>$bank['uuid'],'date'=>$date],$prefix.':loan');$ob=$c->scope('obligations',$loan['uuid'],$h);$borrow=$c->one("SELECT t.* FROM transactions t JOIN journal_entries j ON j.transaction_id=t.id JOIN journal_lines l ON l.journal_id=j.id WHERE l.household_id=? AND l.ledger_id=? AND t.type='borrow'",[$h,$ob['ledger_id']]);$repay=$a->post($h,$u,['type'=>'repay','account_uuid'=>$bank['uuid'],'obligation_uuid'=>$ob['uuid'],'amount'=>'20','date'=>$date],$prefix.':repay');$r=correction($borrow,['amount'=>'120'],$prefix.':borrow-edit');ok(equalMoney($c->balance($h,(int)$ob['ledger_id']),'-100')&&equalMoney($c->scope('obligations',$ob['uuid'],$h)['original_amount'],'120'),'Borrowing can be corrected after repayments without invalid intermediate principal');correction($repay,['amount'=>'30'],$prefix.':repay-edit');ok(equalMoney($c->balance($h,(int)$ob['ledger_id']),'-90'),'Principal repayment can be corrected');$correctedBorrow=$c->scope('transactions',$r['uuid'],$h);fails(fn()=>correction($correctedBorrow,['amount'=>'10'],$prefix.':overpaid-loan'),'Loan corrections cannot overpay principal');
$bankLedger=$c->one('SELECT l.uuid FROM ledger_accounts l JOIN accounts a ON a.ledger_id=l.id WHERE a.household_id=? AND a.uuid=?',[$h,$bank['uuid']])['uuid'];$j=$a->postJournal($h,$u,['date'=>$date,'description'=>'Edit journal','lines'=>[['account_uuid'=>$expense['uuid'],'debit'=>'8','credit'=>'0'],['account_uuid'=>$bankLedger,'debit'=>'0','credit'=>'8']]],$prefix.':journal');correction($j,['lines'=>[['account_uuid'=>$expense['uuid'],'debit'=>'12','credit'=>'0'],['account_uuid'=>$bankLedger,'debit'=>'0','credit'=>'12']]],$prefix.':journal-edit');ok($c->scope('transactions',$j['uuid'],$h)['status']==='reversed','Manual journal editing preserves balanced correction history');
$matched=$a->post($h,$u,['type'=>'expense','account_uuid'=>$bank['uuid'],'category_uuid'=>$cat['uuid'],'amount'=>'15','date'=>$date],$prefix.':matched');$bankId=$c->scope('accounts',$bank['uuid'],$h)['id'];$batch=$c->insert('import_batches',['uuid'=>Core::uuid(),'household_id'=>$h,'account_id'=>$bankId,'created_by'=>$u,'filename'=>'synthetic.csv','file_hash'=>hash('sha256',$prefix),'sheet'=>'','source_json'=>'[]','status'=>'review','created_at'=>Core::now()]);$c->insert('import_links',['household_id'=>$h,'account_id'=>$bankId,'fingerprint'=>hash('sha256',$prefix.':row'),'transaction_id'=>$matched['id'],'batch_id'=>$batch]);fails(fn()=>correction($matched,['amount'=>'16'],$prefix.':bad-match'),'Matched statement amounts cannot silently change');$r=correction($matched,['category_uuid'=>$uncat['uuid']],$prefix.':match-edit');ok($c->query('SELECT transaction_id FROM import_links WHERE household_id=? AND batch_id=?',[$h,$batch])->fetchColumn()==$c->scope('transactions',$r['uuid'],$h)['id'],'Statement provenance follows category corrections');
$ledger=$c->scope('ledger_accounts',$expense['uuid'],$h);$manage->update($h,$u,['uuid'=>$ledger['uuid'],'expected_name'=>$ledger['name'],'expected_active'=>1,'action'=>'rename','name'=>'Renamed expense '.$prefix],$prefix.':rename');ok($c->scope('categories',$cat['uuid'],$h)['name']==='Renamed expense '.$prefix,'Renaming a chart leaf updates its transaction category');
$before=$c->balance($h,(int)$c->scope('accounts',$bank['uuid'],$h)['ledger_id']);$move=$edit->moveCategory($h,$u,['source_uuid'=>$cat['uuid'],'target_uuid'=>$uncat['uuid'],'reason'=>'Move to Uncategorized','archive'=>true],$prefix.':move');ok($move['moved']>=3&&$c->scope('ledger_accounts',$ledger['uuid'],$h)['active']==0,'Move entries corrects simple, split, bill and journal entries then archives the source');ok(equalMoney($before,$c->balance($h,(int)$c->scope('accounts',$bank['uuid'],$h)['ledger_id'])),'Category moves leave bank balances unchanged');ok($c->scope('bills',$bill['uuid'],$h)['category_id']==$uncat['id'],'Category moves retain bill links and move plans');
$snapshot=$f->snapshot($h,['name'=>'Test','email'=>'test@example.invalid','role'=>'owner']);ok(count(array_filter($snapshot['transactions'],fn($t)=>$t['status']==='posted'&&$t['needs_review']))>0,'Uncategorized split transactions appear in Needs review');
$archived=$c->scope('ledger_accounts',$ledger['uuid'],$h);$manage->update($h,$u,['uuid'=>$archived['uuid'],'expected_name'=>$archived['name'],'expected_active'=>0,'action'=>'restore'],$prefix.':restore-category');ok($c->scope('ledger_accounts',$ledger['uuid'],$h)['active']==1,'Archived categories can be restored');
$empty=$f->create($h,$u,'account',['name'=>'Empty archive '.$prefix,'opening'=>'0','date'=>$date],$prefix.':empty');$emptyA=$c->scope('accounts',$empty['uuid'],$h);$manage->update($h,$u,['uuid'=>$emptyA['uuid'],'expected_name'=>$emptyA['name'],'expected_active'=>1,'action'=>'archive'],$prefix.':archive-bank',true);ok($c->scope('accounts',$emptyA['uuid'],$h)['active']==0,'Zero-balance money accounts can be archived');fails(fn()=>$a->post($h,$u,['type'=>'income','account_uuid'=>$emptyA['uuid'],'category_uuid'=>$inc['uuid'],'amount'=>'1','date'=>$date],$prefix.':inactive-post'),'Archived money accounts reject postings');$manage->update($h,$u,['uuid'=>$emptyA['uuid'],'expected_name'=>$emptyA['name'],'expected_active'=>0,'action'=>'restore'],$prefix.':restore-bank',true);ok($c->scope('accounts',$emptyA['uuid'],$h)['active']==1,'Money accounts can be restored');$nonzero=$c->scope('accounts',$bank['uuid'],$h);fails(fn()=>$manage->update($h,$u,['uuid'=>$nonzero['uuid'],'expected_name'=>$nonzero['name'],'expected_active'=>1,'action'=>'archive'],$prefix.':nonzero',true),'Nonzero bank balances require a transfer before archiving');
$emptyCurrent=$c->scope('accounts',$emptyA['uuid'],$h);$manage->update($h,$u,['uuid'=>$emptyCurrent['uuid'],'expected_name'=>$emptyCurrent['name'],'expected_active'=>1,'action'=>'rename','name'=>$emptyCurrent['name'],'type'=>'cash'],$prefix.':bank-type',true);ok($c->scope('accounts',$emptyA['uuid'],$h)['type']==='cash','Asset accounts can change between bank, cash, wallet and savings types');fails(fn()=>$manage->update($h,$u,['uuid'=>$emptyCurrent['uuid'],'expected_name'=>$emptyCurrent['name'],'expected_active'=>1,'action'=>'rename','name'=>$emptyCurrent['name'],'type'=>'credit_card'],$prefix.':class-change',true),'Account detail edits cannot silently change asset to liability');
$f->create($h,$u,'budget',['category_uuid'=>$cat['uuid'],'month'=>$month,'amount'=>'10'],$prefix.':budget-source');$f->create($h,$u,'budget',['category_uuid'=>$uncat['uuid'],'month'=>$month,'amount'=>'15'],$prefix.':budget-target');fails(fn()=>$edit->moveCategory($h,$u,['source_uuid'=>$cat['uuid'],'target_uuid'=>$uncat['uuid'],'reason'=>'Conflicting budget','archive'=>true],$prefix.':budget-conflict'),'Category moves with conflicting monthly budgets are rejected atomically');$activeCategory=$c->scope('ledger_accounts',$ledger['uuid'],$h);fails(fn()=>$manage->update($h,$u,['uuid'=>$activeCategory['uuid'],'expected_name'=>$activeCategory['name'],'expected_active'=>1,'action'=>'archive'],$prefix.':planned-category'),'Active category budgets prevent silent archiving');
$attachmentTxn=$a->post($h,$u,['type'=>'income','account_uuid'=>$bank['uuid'],'category_uuid'=>$inc['uuid'],'amount'=>'1','date'=>$date],$prefix.':attachment-txn');$storageKey=bin2hex(random_bytes(32));$documentDir=$c->config['storage'].'/documents';if(!is_dir($documentDir))mkdir($documentDir,0700,true);$blob=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=');file_put_contents($documentDir.'/'.$storageKey,$blob);$docUuid=Core::uuid();$c->insert('documents',['uuid'=>$docUuid,'household_id'=>$h,'transaction_id'=>$attachmentTxn['id'],'filename'=>'synthetic.png','storage_key'=>$storageKey,'mime'=>'image/png','bytes'=>strlen($blob),'checksum'=>hash('sha256',$blob),'created_at'=>Core::now()]);$r=correction($attachmentTxn,['description'=>'Updated attachment note'],$prefix.':attachment-edit');ok($c->scope('documents',$docUuid,$h)['transaction_id']==$c->scope('transactions',$r['uuid'],$h)['id'],'Private attachments remain linked to the corrected transaction');
$edit->moveCategory($h,$u,['source_uuid'=>$cat['uuid'],'target_uuid'=>$uncat['uuid'],'reason'=>'Combine category budgets','archive'=>true,'combine_budgets'=>true],$prefix.':combine-budgets');ok(equalMoney($c->query('SELECT amount FROM budgets WHERE household_id=? AND category_id=? AND month=?',[$h,$uncat['id'],$month])->fetchColumn(),'25'),'Explicit budget combination adds planned amounts without losing budget rows');ok($c->scope('ledger_accounts',$ledger['uuid'],$h)['active']==0&&((new \ReadyFinance\PlanManagementService($c))->ready()?(bool)$c->query('SELECT archived FROM budgets WHERE household_id=? AND category_id=? AND month=?',[$h,$cat['id'],$month])->fetchColumn():equalMoney($c->query('SELECT amount FROM budgets WHERE household_id=? AND category_id=? AND month=?',[$h,$cat['id'],$month])->fetchColumn(),'0')),'Moved budget source can be archived with history retained');
$root=$c->one("SELECT * FROM ledger_accounts WHERE household_id=? AND system_key='chart_root_expense'",[$h]);fails(fn()=>$manage->update($h,$u,['uuid'=>$root['uuid'],'expected_name'=>$root['name'],'expected_active'=>1,'action'=>'archive'],$prefix.':root'),'Main account headings cannot be archived');
$report=$chart->report($h,substr($date,0,4).'-01-01',$date);ok(equalMoney($report['totals']['balance_sheet_difference'],'0')&&equalMoney($report['totals']['closing_debit'],$report['totals']['closing_credit']),'Reports reconcile after all edits, moves and archives');ok(!$c->one('SELECT journal_id FROM journal_lines WHERE household_id=? GROUP BY journal_id HAVING SUM(debit)<>SUM(credit)',[$h]),'Every original, reversal and replacement journal balances');
